def solve():
    def parse_input():
        lines = sys.stdin.read().splitlines()
        t = int(lines[0])
        cases = []
        idx = 1
        for _ in range(t):
            k = int(lines[idx])
            grid = []
            for i in range(2):
                row = lines[idx + 1 + i].split()
                grid.append(row)
            cases.append((k, grid))
            idx += 3
        return cases

