        for i in range(2):
            for j in range(len(grid[i])):
                if grid[i][j] == target:
                    return (i, j)
        return (-1, -1)

    def is_valid_move(grid, ei, ej, di, dj):
        ni, nj = ei + di, ej + dj
        if ni < 0 or ni >= 2 or nj < 0 or nj >= len(grid[0]):
            return False
        if grid[ni][nj] == 'E':
            return False
        if di == 0:  # horizontal move
            return True
        else:  # vertical move
            if ej == 0 or ej == len(grid[0]) - 1 or ej == len(grid[0]) // 2:
                return True
            else:
                return False

    def get_possible_moves(grid, ei, ej):
        moves = []
        if ei > 0 and is_valid_move(grid, ei, ej, -1, 0):
            moves.append(('u', ei - 1, ej))
        if ei < 1 and is_valid_move(grid, ei, ej, 1, 0):
            moves.append(('d', ei + 1, ej))
        if ej > 0 and is_valid_move(grid, ei, ej, 0, -1):
            moves.append(('l', ei, ej - 1))
        if ej < len(grid[0]) - 1 and is_valid_move(grid, ei, ej, 0, 1):
            moves.append(('r', ei, ej + 1))
        return moves

    def bfs(grid, k):
        target_grid = []
        for i in range(2):
            row = []
            for j in range(2*k + 1):
                if i == 0:
                    row.append(str(j + 1))
                else:
                    if j < 2*k + 1:
                        row.append(str(2*k + 2 + j))
                    else:
                        row.append('E')
            target_grid.append(row)

        start_e_pos = find_pos(grid, 'E')
        target_e_pos = find_pos(target_grid, 'E')

        if start_e_pos == target_e_pos:
            return []

        visited = set()
        queue = deque()
        queue.append((start_e_pos[0], start_e_pos[1], []))
        visited.add((start_e_pos[0], start_e_pos[1], tuple(tuple(row) for row in grid)))

        while queue:
            ei, ej, path = queue.popleft()
            current_grid = [list(row) for row in grid]
            current_grid[ei][ej] = 'E'
            for move, ni, nj in get_possible_moves(current_grid, ei, ej):
                new_grid = [row[:] for row in current_grid]
                new_grid[ei][ej], new_grid[ni][nj] = new_grid[ni][nj], new_grid[ei][ej]
                new_state = (ni, nj, tuple(tuple(row) for row in new_grid))
                if new_state in visited:
                    continue
                visited.add(new_state)
                if tuple(tuple(row) for row in new_grid) == tuple(tuple(row) for row in target_grid):
                    return path + [move]
                queue.append((ni, nj, path + [move]))
        return None

    def solve_case(k, grid):
        moves = bfs(grid, k)
        if moves is None:
            return "SURGERY FAILED"
        else:
            return "SURGERY COMPLETE", moves

    cases = parse_input()
